INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('air-cars-world', 'Atari Jaguar', 'Air Cars (World)', '1995', 'Simulation', 'SCISYS', '1', 'Flight combat simulation', 'First-person 3D vehicle combat and exploration.', 'Navigate post-apocalyptic landscapes to destroy enemy bases and vehicles.', 'A futuristic hovercraft shooter featuring open-world 3D environments.', 'Air Cars on Atari Jaguar delivers intense vehicle-based combat. Explore vast 3D terrains and engage in tactical dogfights in this early example of open-world shooter mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alien-vs-predator-world', 'Atari Jaguar', 'Alien vs Predator (World)', '1994', 'Action', 'Fox Interactive / Rebellion', '1-2', 'First-person sci-fi shooter', 'First-person survival horror with three distinct campaigns.', 'Survive as a Marine, hunt as a Predator, or infest as an Alien.', 'A legendary masterpiece and the definitive "killer app" for the Jaguar.', 'Alien vs Predator for Atari Jaguar is a survival horror landmark. Experience three unique gameplay styles with digitized graphics and an oppressive atmosphere in this 64-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atari-karts-world', 'Atari Jaguar', 'Atari Karts (World)', '1995', 'Racing', 'Atari', '1-2', 'Arcade kart racing', 'Pseudo-3D kart racing with power-ups and themed tracks.', 'Win the Atari Cup by finishing first in a series of whimsical races.', 'A colorful and fast-paced kart racer featuring classic Atari-themed environments.', 'Atari Karts on Jaguar offers vibrant 64-bit racing action. Choose your character and master the power-ups to dominate the tracks in this rare and charming kart racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('attack-of-the-mutant-penguins-world', 'Atari Jaguar', 'Attack of the Mutant Penguins (World)', '1995', 'Action', 'Sunsoft', '1', 'Run-and-gun action', 'Isometric action-puzzle game with tower defense elements.', 'Protect the Earth from an invasion of evil mutated penguins.', 'A quirky and surreal strategy game featuring unique character designs.', 'Attack of the Mutant Penguins for Atari Jaguar is a bizarrely fun cult classic. Manage your resources and use wacky gadgets to repel the avian invasion in this visually distinct title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-sphere-gold-world', 'Atari Jaguar', 'Battle Sphere Gold (World)', '1998', 'Shooter', '4Play / Scatologic', '1-2', 'Multiplayer space combat shooter', 'First-person 3D space combat simulator.', 'Engage in massive intergalactic dogfights to protect your star system.', 'An improved and definitive version of the most advanced space sim on the system.', 'Battle Sphere Gold on Atari Jaguar represents the peak of 64-bit space combat. Featuring a sophisticated physics engine and intense multiplayer, it’s a technical marvel for the platform.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brutal-sports-football-world', 'Atari Jaguar', 'Brutal Sports Football (World)', '1995', 'Sports', 'Millennium Interactive', '1-2', 'Futuristic violent sports', 'Top-down violent sports-action hybrid.', 'Win a game of futuristic football by any means necessary, including violence.', 'A brutal and humorous take on American football with combat elements.', 'Brutal Sports Football for Atari Jaguar brings high-impact sports action. Tackle, punch, and kick your way to victory in this fast-paced and gory 64-bit arcade sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bubsy-in-fractured-furry-tales-world', 'Atari Jaguar', 'Bubsy in Fractured Furry Tales (World)', '1994', 'Platformer', 'Imagitec Design', '1', 'Cartoon platformer', 'Side-scrolling 2D platformer with high-speed movement.', 'Navigate through fairy-tale themed worlds to defeat various bosses.', 'A visually sharp 64-bit entry in the Bubsy series with large levels.', 'Bubsy in Fractured Furry Tales on Atari Jaguar features detailed graphics and classic platforming. Guide Bubsy through surreal environments in this challenging and pun-filled adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cannon-fodder-world', 'Atari Jaguar', 'Cannon Fodder (World)', '1995', 'Strategy', 'Sensible Software', '1-2', 'Real-time tactical action', 'Top-down tactical squad-based action game.', 'Lead a small troop of soldiers through dangerous missions across various warzones.', 'A dark, humorous, and highly addictive military strategy-action port.', 'Cannon Fodder for Atari Jaguar offers precise tactical controls and high-fidelity sound. Manage your squad’s survival in this acclaimed 64-bit port of the war-gaming classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('checkered-flag-world', 'Atari Jaguar', 'Checkered Flag (World)', '1994', 'Racing', 'Atari', '1-2', 'Arcade racing', 'Third-person 3D polygonal racing game.', 'Outrace your opponents on a variety of challenging tropical tracks.', 'An early 3D racing showcase for the Jaguar featuring customizable cars.', 'Checkered Flag on Atari Jaguar pushes the system''s 3D capabilities. Master the handling of your Formula 1 car in this technically ambitious and visually distinct racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('club-drive-world', 'Atari Jaguar', 'Club Drive (World)', '1995', 'Racing', 'Atari', '1-2', 'Stunt-based arcade driving', 'Third-person 3D exploration and driving simulation.', 'Explore a futuristic city and complete various driving challenges.', 'A unique 3D driving game known for its surreal world and open exploration.', 'Club Drive for Atari Jaguar offers a non-traditional racing experience. Navigate through indoor and outdoor 3D environments in this experimental 64-bit driving title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cybermorph-world-rev-1', 'Atari Jaguar', 'Cybermorph (World) (Rev 1)', '1993', 'Shooter', 'Attention to Detail', '1', 'First-person shooter', 'Third-person 3D flight combat and exploration.', 'Recover lost technology pods across various planets while fighting enemies.', 'The system''s pack-in title featuring impressive 3D polygons and voice acting.', 'Cybermorph (Rev 1) on Atari Jaguar is a definitive 64-bit experience. Pilot the trans-morphing T-Rex fighter through open 3D worlds in this groundbreaking space combat game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cybermorph-world-rev-2', 'Atari Jaguar', 'Cybermorph (World) (Rev 2)', '1993', 'Shooter', 'Attention to Detail', '1', 'First-person shooter', 'Third-person 3D flight combat and exploration.', 'Recover lost technology pods across various planets while fighting enemies.', 'An updated revision of the pack-in title with refined gameplay and audio.', 'Cybermorph (Rev 2) for Atari Jaguar provides the most stable version of this 3D classic. Experience improved voice cues and smoother performance in this essential 64-bit shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('defender-2000-world', 'Atari Jaguar', 'Defender 2000 (World)', '1995', 'Shooter', 'Midway', '1-2', 'Arcade shooter remake', 'High-speed side-scrolling shooter with "remix" and classic modes.', 'Protect humans from abduction while destroying waves of alien enemies.', 'A Jeff Minter "remix" of the arcade classic with psychedelic visuals.', 'Defender 2000 on Atari Jaguar is an explosion of color and speed. Experience this trippy 64-bit overhaul of the arcade legend with new power-ups and a pulsing soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doom-world', 'Atari Jaguar', 'Doom (World)', '1994', 'Shooter', 'id Software / Atari', '1', 'First-person shooter', 'First-person shooter with intense action and exploration.', 'Fight your way through a demon-infested moon base to reach Earth.', 'A technically impressive port of the FPS legend featuring fluid 64-bit graphics.', 'Doom for Atari Jaguar is one of the best console ports of its time. Experience fast, full-screen action and visceral combat in this definitive 16-bit era transition masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('double-dragon-v---the-shadow-falls-world', 'Atari Jaguar', 'Double Dragon V - The Shadow Falls (World)', '1995', 'Fighting', 'Leland Interactive Media', '1-2', 'Arcade-style fighting', 'One-on-one 2D fighting game based on the cartoon series.', 'Defeat the Shadow Master and his henchmen in a martial arts tournament.', 'A colorful fighter featuring a large roster and diverse special moves.', 'Double Dragon V on Atari Jaguar brings the classic franchise into the fighting genre. Master unique combos and finishers in this 64-bit port of the competitive combat title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon---the-bruce-lee-story-world', 'Atari Jaguar', 'Dragon - The Bruce Lee Story (World)', '1995', 'Action', 'Virgin Interactive', '1', 'Cinematic martial arts action', 'Side-scrolling martial arts brawler and fighting game.', 'Relive the legendary life of Bruce Lee by defeating his most iconic rivals.', 'A visually stunning fighter featuring fluid animation and multiple styles.', 'Dragon: The Bruce Lee Story for Atari Jaguar offers a high-fidelity martial arts experience. Master Bruce''s speed and philosophy in this polished 64-bit cinematic brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('evolution---dino-dudes-world', 'Atari Jaguar', 'Evolution - Dino Dudes (World)', '1994', 'Action', 'Visual Concepts', '1', 'Run-and-gun platform action', 'Side-scrolling puzzle-platformer with Lemmings-style mechanics.', 'Guide a group of cavemen to safety through hazardous prehistoric levels.', 'A humorous and challenging puzzle game with detailed 2D sprites.', 'Evolution: Dino Dudes on Atari Jaguar features clever level design and quirky 64-bit visuals. Manage your tribe''s survival in this expansive and addictive prehistoric quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fever-pitch-soccer-world-enfrdeesit', 'Atari Jaguar', 'Fever Pitch Soccer (World) (En,Fr,De,Es,It)', '1996', 'Sports', 'Codemasters', '1-2', 'Arcade soccer', 'Isometric 2D soccer simulation with arcade elements.', 'Lead your chosen national team to victory in an international tournament.', 'A fast-paced soccer game with smooth animation and multiple language support.', 'Fever Pitch Soccer for Atari Jaguar offers high-energy sports action. Utilize power-ups and special moves to dominate the field in this colorful 64-bit football sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fight-for-life-world', 'Atari Jaguar', 'Fight for Life (World)', '1996', 'Fighting', 'Atari', '1-2', '3D fighting game', 'One-on-one 3D polygonal fighting game.', 'Defeat a series of opponents to earn your freedom from a high-tech prison.', 'A technical showcase of the Jaguar''s ability to handle 3D character models.', 'Fight for Life on Atari Jaguar is a milestone as the system''s first true 3D fighter. Master the tactical combat and diverse move sets in this ambitious 64-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fight-for-life-world-alt-1', 'Atari Jaguar', 'Fight for Life (World) (Alt 1)', '1996', 'Fighting', 'Atari', '1-2', '3D fighting game', 'One-on-one 3D polygonal fighting game.', 'Defeat a series of opponents to earn your freedom from a high-tech prison.', 'An alternate version of the system''s technical 3D fighting game.', 'Fight for Life (Alt 1) for Atari Jaguar offers a variation on the tactical 3D combat experience. Engage in fluid polygonal battles in this rare edition of the system''s complex fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flashback---the-quest-for-identity-world-enfr', 'Atari Jaguar', 'Flashback - The Quest for Identity (World) (En,Fr)', '1994', 'Action-adventure', 'Delphine Software', '1', 'Cinematic platform adventure', 'Cinematic action-platformer with rotoscoped animation and FMV.', 'Recover your memories and save Earth from an alien conspiracy.', 'A high-fidelity port featuring enhanced music and cinematic sequences.', 'Flashback on Atari Jaguar delivers the ultimate version of this sci-fi classic. Experience the fluid animation and deep story with the benefit of 64-bit hardware performance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flip-out!-world', 'Atari Jaguar', 'Flip Out! (World)', '1995', 'Puzzle', 'System 3', '1', 'Action puzzle game', 'Isometric 3D puzzle and physics-based action game.', 'Help a troupe of aliens navigate through various levels by tossing them around.', 'A quirky, colorful, and unique puzzle title that uses the Jaguar''s power well.', 'Flip Out! for Atari Jaguar is a hidden gem of creative gameplay. Master the physics and timing of this alien-tossing adventure in one of the most original 64-bit titles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hover-strike-world', 'Atari Jaguar', 'Hover Strike (World)', '1995', 'Shooter', 'Atari', '1', 'FPS tank combat', 'Third-person 3D tank combat and orbital bombardment.', 'Repel an alien invasion by destroying ground targets and aerial threats.', 'A gritty 3D shooter with a focus on heavy artillery and exploration.', 'Hover Strike on Atari Jaguar brings intense hovercraft warfare. Navigate through dark, atmospheric 3D environments and utilize a variety of advanced weapons to save the planet.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hyper-force-world', 'Atari Jaguar', 'Hyper Force (World)', '1995', 'Shooter', 'Atari', '1', 'Arcade sci-fi shooter', 'Side-scrolling 2D action-shooter with futuristic themes.', 'Infiltrate enemy bases and destroy robotic sentries across multiple stages.', 'A fast-paced "run and gun" shooter with impressive sprite scaling.', 'Hyper Force for Atari Jaguar is an underrated action powerhouse. Experience the speed and firepower of 64-bit combat in this challenging and visually detailed futuristic quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('i-war-world', 'Atari Jaguar', 'I-War (World)', '1995', 'Shooter', 'Atari / Beyond Games', '1', 'First-person mech shooter', 'First-person 3D space combat and strategy simulation.', 'Defend your territory from enemy forces in high-speed space dogfights.', 'A technically advanced shooter featuring Gouraud-shaded 3D graphics.', 'I-War on Atari Jaguar offers a sleek and modern take on the space shooter. Master the 3D flight mechanics and engage in tactical intergalactic warfare with smooth 64-bit visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('iron-soldier-world-v104', 'Atari Jaguar', 'Iron Soldier (World) (v1.04)', '1994', 'Shooter', 'Eclipse Software', '1', 'Mech combat shooter', 'First-person 3D mech combat simulator with multiple missions.', 'Pilot a massive robotic soldier to complete sabotage and destruction objectives.', 'One of the most highly-rated games on the system featuring solid 3D graphics.', 'Iron Soldier on Atari Jaguar (v1.04) is a definitive mech sim experience. Feel the weight and power of 64-bit urban combat in this technically impressive 3D masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('iron-soldier-2-world', 'Atari Jaguar', 'Iron Soldier 2 (World)', '1997', 'Shooter', 'Eclipse Software', '1', 'Mech combat shooter', 'First-person 3D mech combat with enhanced graphics and audio.', 'Command an advanced mech to stop a rogue corporation’s military coup.', 'The massive sequel featuring improved textures, new weapons, and FMV.', 'Iron Soldier 2 for Atari Jaguar expands the mech-warfare genre. Experience high-fidelity 64-bit destruction and refined 3D mechanics in this premier robotic combat simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kasumi-ninja-world', 'Atari Jaguar', 'Kasumi Ninja (World)', '1994', 'Fighting', 'Handmade Software', '1-2', 'Weapon-based fighting', 'One-on-one 2D fighting game with digitized characters.', 'Defeat opponents from different time periods to stop an ancient evil.', 'A controversial but visually unique fighter featuring large digitized sprites.', 'Kasumi Ninja on Atari Jaguar brings brutal combat to the 64-bit era. Master the unique special moves of mystical warriors in this dark and gore-filled fighting title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('missile-command-3d-world', 'Atari Jaguar', 'Missile Command 3D (World)', '1995', 'Shooter', 'High Voltage Software', '1', '3D arcade missile defense', 'First-person 3D shooter with three distinct gameplay modes.', 'Protect your cities from incoming nuclear missiles and alien attacks.', 'A modern 64-bit reimagining of the arcade classic with VR support.', 'Missile Command 3D for Atari Jaguar is a stunning technical update. Experience the intense defensive action in three different graphical styles, including a full 3D "Virtual" mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-jam---tournament-edition-world', 'Atari Jaguar', 'NBA Jam - Tournament Edition (World)', '1995', 'Sports', 'Iguana Entertainment', '1-4', 'Arcade basketball', 'Two-on-two arcade-style basketball with power-ups and dunks.', 'Outscore your opponents in high-flying matches to win the tournament.', 'An excellent port featuring all the "on fire" action of the arcade.', 'NBA Jam: Tournament Edition on Atari Jaguar delivers the ultimate home version of the hit. Experience the speed and high-fidelity audio of 64-bit arcade basketball.');
