INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-war-2000-world', 'Atari Jaguar', 'Space War 2000 (World)', '1996', 'Shooter', 'Atari', '1', 'Top-down space shooter', 'Third-person 3D flight combat and exploration.', 'Recover lost technology pods across various planets while fighting enemies.', 'The system''s pack-in title featuring impressive 3D polygons and voice acting.', 'Cybermorph (Rev 1) on Atari Jaguar is a definitive 64-bit experience. Pilot the trans-morphing T-Rex fighter through open 3D worlds in this groundbreaking space combat game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-burnout-world', 'Atari Jaguar', 'Super Burnout (World)', '1995', 'Racing', 'Digital Illusions', '1-2', 'Motorcycle arcade racing', 'Third-person 3D flight combat and exploration.', 'Recover lost technology pods across various planets while fighting enemies.', 'An updated revision of the pack-in title with refined gameplay and audio.', 'Cybermorph (Rev 2) for Atari Jaguar provides the most stable version of this 3D classic. Experience improved voice cues and smoother performance in this essential 64-bit shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('supercross-3d-world', 'Atari Jaguar', 'SuperCross 3D (World)', '1995', 'Racing', 'Atari', '1-2', 'Off-road motocross racing', 'High-speed side-scrolling shooter with "remix" and classic modes.', 'Protect humans from abduction while destroying waves of alien enemies.', 'A Jeff Minter "remix" of the arcade classic with psychedelic visuals.', 'Defender 2000 on Atari Jaguar is an explosion of color and speed. Experience this trippy 64-bit overhaul of the arcade legend with new power-ups and a pulsing soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('syndicate-world', 'Atari Jaguar', 'Syndicate (World)', '1995', 'Strategy', 'Bullfrog Productions', '1', 'Real-time tactical strategy', 'First-person shooter with intense action and exploration.', 'Fight your way through a demon-infested moon base to reach Earth.', 'A technically impressive port of the FPS legend featuring fluid 64-bit graphics.', 'Doom for Atari Jaguar is one of the best console ports of its time. Experience fast, full-screen action and visceral combat in this definitive 16-bit era transition masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tempest-2000-world', 'Atari Jaguar', 'Tempest 2000 (World)', '1994', 'Action', 'Llamasoft', '1-2', 'Psychedelic arcade shooter', 'One-on-one 2D fighting game based on the cartoon series.', 'Defeat the Shadow Master and his henchmen in a martial arts tournament.', 'A colorful fighter featuring a large roster and diverse special moves.', 'Double Dragon V on Atari Jaguar brings the classic franchise into the fighting genre. Master unique combos and finishers in this 64-bit port of the competitive combat title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('thea-realm-fighters-early-prototype', 'Atari Jaguar', 'Thea Realm Fighters (Early prototype)', '1996', 'Fighting', 'Atari', '1-2', 'Prototype 2D fighting game', 'Side-scrolling martial arts brawler and fighting game.', 'Relive the legendary life of Bruce Lee by defeating his most iconic rivals.', 'A visually stunning fighter featuring fluid animation and multiple styles.', 'Dragon: The Bruce Lee Story for Atari Jaguar offers a high-fidelity martial arts experience. Master Bruce''s speed and philosophy in this polished 64-bit cinematic brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('theme-park-world', 'Atari Jaguar', 'Theme Park (World)', '1995', 'Simulation', 'Bullfrog Productions', '1', 'Theme park management sim', 'Side-scrolling puzzle-platformer with Lemmings-style mechanics.', 'Guide a group of cavemen to safety through hazardous prehistoric levels.', 'A humorous and challenging puzzle game with detailed 2D sprites.', 'Evolution: Dino Dudes on Atari Jaguar features clever level design and quirky 64-bit visuals. Manage your tribe''s survival in this expansive and addictive prehistoric quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('total-carnage-world', 'Atari Jaguar', 'Total Carnage (World)', '1994', 'Shooter', 'Midway', '1-2', 'Run-and-gun arcade shooter', 'Isometric 2D soccer simulation with arcade elements.', 'Lead your chosen national team to victory in an international tournament.', 'A fast-paced soccer game with smooth animation and multiple language support.', 'Fever Pitch Soccer for Atari Jaguar offers high-energy sports action. Utilize power-ups and special moves to dominate the field in this colorful 64-bit football sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('towers-ii-world', 'Atari Jaguar', 'Towers II (World)', '1994', 'RPG', 'Lawrence Holland Productions', '1', 'First-person dungeon RPG', 'One-on-one 3D polygonal fighting game.', 'Defeat a series of opponents to earn your freedom from a high-tech prison.', 'A technical showcase of the Jaguar''s ability to handle 3D character models.', 'Fight for Life on Atari Jaguar is a milestone as the system''s first true 3D fighter. Master the tactical combat and diverse move sets in this ambitious 64-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('trevor-mcfur-in-the-crescent-galaxy-world', 'Atari Jaguar', 'Trevor McFur in the Crescent Galaxy (World)', '1995', 'Platformer', 'Atari', '1', 'Action platformer', 'One-on-one 3D polygonal fighting game.', 'Defeat a series of opponents to earn your freedom from a high-tech prison.', 'An alternate version of the system''s technical 3D fighting game.', 'Fight for Life (Alt 1) for Atari Jaguar offers a variation on the tactical 3D combat experience. Engage in fluid polygonal battles in this rare edition of the system''s complex fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('troy-aikman-nfl-football-world', 'Atari Jaguar', 'Troy Aikman NFL Football (World)', '1995', 'Sports', 'Leland Interactive Media', '1-2', 'American football arcade', 'Cinematic action-platformer with rotoscoped animation and FMV.', 'Recover your memories and save Earth from an alien conspiracy.', 'A high-fidelity port featuring enhanced music and cinematic sequences.', 'Flashback on Atari Jaguar delivers the ultimate version of this sci-fi classic. Experience the fluid animation and deep story with the benefit of 64-bit hardware performance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultra-vortek-world', 'Atari Jaguar', 'Ultra Vortek (World)', '1996', 'Fighting', 'Atari', '1-2', 'Weapon-based fighting', 'Isometric 3D puzzle and physics-based action game.', 'Help a troupe of aliens navigate through various levels by tossing them around.', 'A quirky, colorful, and unique puzzle title that uses the Jaguar''s power well.', 'Flip Out! for Atari Jaguar is a hidden gem of creative gameplay. Master the physics and timing of this alien-tossing adventure in one of the most original 64-bit titles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultra-vortek-world-v094-beta', 'Atari Jaguar', 'Ultra Vortek (World) (v0.94) (Beta)', '1996', 'Fighting', 'Atari', '1-2', 'Weapon-based fighting', 'Third-person 3D tank combat and orbital bombardment.', 'Repel an alien invasion by destroying ground targets and aerial threats.', 'A gritty 3D shooter with a focus on heavy artillery and exploration.', 'Hover Strike on Atari Jaguar brings intense hovercraft warfare. Navigate through dark, atmospheric 3D environments and utilize a variety of advanced weapons to save the planet.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('val-disere-skiing-and-snowboarding-world', 'Atari Jaguar', 'Val d''Isere Skiing and Snowboarding (World)', '1996', 'Sports', 'Val d''Isere Skiing Team', '1', 'Skiing and snowboarding sports', 'Side-scrolling 2D action-shooter with futuristic themes.', 'Infiltrate enemy bases and destroy robotic sentries across multiple stages.', 'A fast-paced "run and gun" shooter with impressive sprite scaling.', 'Hyper Force for Atari Jaguar is an underrated action powerhouse. Experience the speed and firepower of 64-bit combat in this challenging and visually detailed futuristic quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('white-men-cant-jump-world', 'Atari Jaguar', 'White Men Can''t Jump (World)', '1995', 'Sports', 'High Voltage Software', '1-2', 'Arcade basketball', 'First-person 3D space combat and strategy simulation.', 'Defend your territory from enemy forces in high-speed space dogfights.', 'A technically advanced shooter featuring Gouraud-shaded 3D graphics.', 'I-War on Atari Jaguar offers a sleek and modern take on the space shooter. Master the 3D flight mechanics and engage in tactical intergalactic warfare with smooth 64-bit visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wolfenstein-3d-world', 'Atari Jaguar', 'Wolfenstein 3D (World)', '1994', 'Shooter', 'id Software / Atari', '1', 'First-person shooter', 'First-person 3D mech combat simulator with multiple missions.', 'Pilot a massive robotic soldier to complete sabotage and destruction objectives.', 'One of the most highly-rated games on the system featuring solid 3D graphics.', 'Iron Soldier on Atari Jaguar (v1.04) is a definitive mech sim experience. Feel the weight and power of 64-bit urban combat in this technically impressive 3D masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('worms-world', 'Atari Jaguar', 'Worms (World)', '1995', 'Strategy', 'Team17', '1-4', 'Turn-based artillery strategy', 'First-person 3D mech combat with enhanced graphics and audio.', 'Command an advanced mech to stop a rogue corporation’s military coup.', 'The massive sequel featuring improved textures, new weapons, and FMV.', 'Iron Soldier 2 for Atari Jaguar expands the mech-warfare genre. Experience high-fidelity 64-bit destruction and refined 3D mechanics in this premier robotic combat simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zero-5-world', 'Atari Jaguar', 'Zero 5 (World)', '1997', 'Shooter', 'Beyond Games', '1', 'High-speed space shooter', 'One-on-one 2D fighting game with digitized characters.', 'Defeat opponents from different time periods to stop an ancient evil.', 'A controversial but visually unique fighter featuring large digitized sprites.', 'Kasumi Ninja on Atari Jaguar brings brutal combat to the 64-bit era. Master the unique special moves of mystical warriors in this dark and gore-filled fighting title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zool-2-world', 'Atari Jaguar', 'Zool 2 (World)', '1995', 'Platformer', 'Gremlin Interactive', '1', 'Cartoon platformer', 'First-person 3D shooter with three distinct gameplay modes.', 'Protect your cities from incoming nuclear missiles and alien attacks.', 'A modern 64-bit reimagining of the arcade classic with VR support.', 'Missile Command 3D for Atari Jaguar is a stunning technical update. Experience the intense defensive action in three different graphical styles, including a full 3D "Virtual" mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zoop!-world', 'Atari Jaguar', 'Zoop! (World)', '1995', 'Puzzle', 'Viacom New Media', '1', 'Arcade puzzle action', 'Two-on-two arcade-style basketball with power-ups and dunks.', 'Outscore your opponents in high-flying matches to win the tournament.', 'An excellent port featuring all the "on fire" action of the arcade.', 'NBA Jam: Tournament Edition on Atari Jaguar delivers the ultimate home version of the hit. Experience the speed and high-fidelity audio of 64-bit arcade basketball.');